chunks.TargetContent:
if (isUnmasked) {
  const fillColor = isSelected ? "#1B8CFE" : "rgba(224, 238, 255, 0.55)";
  const fillOpacity = isSelected ? 0.9 : 0.55;
  const strokeColor = isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.4)";
  const strokeWidth = isSelected ? 2 : 0.8;

  const poly = L.polygon(latlngs, {
    color: strokeColor,
    weight: strokeWidth,
    fillColor,
    fillOpacity,
    className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
  });

